const delay=ms=>new Promise(r=>setTimeout(r,ms));
function url(route,extra={}){const u=new URL(route,BASE);u.searchParams.set('preview_theme_id',THEME);for(const[k,v]of Object.entries(extra))u.searchParams.set(k,String(v));return u.toString()}
async function nav(page,target){let err;for(let i=0;i<3;i++){try{const r=await page.goto(target,{waitUntil:'domcontentloaded',timeout:25000});const status=r?.status()||0;if(status===200){await delay(700);return status}err=new Error('HTTP '+status);if(![429,500,502,503,504].includes(status))break}catch(e){err=e}await delay(1500*(i+1))}throw err||new Error('navigation failed')}
function visible(el){if(!el)return false;const s=getComputedStyle(el),r=el.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0}
async function checkCollection(page,route){await page.waitForSelector('.sq-refine-v3-sidebar',{state:'visible',timeout:12000});return page.evaluate((root)=>{const side=document.querySelector('.sq-refine-v3-sidebar'),size=document.querySelector('.sq-refine-v3-page-size'),groups=[...side.querySelectorAll('.sq-refine-v3-group')],grid=document.querySelector('#ResultsList')||document.querySelector('.product-grid'),old='[data-sq-global-refine-products],.sq-refine-taxonomy-products,[data-sq-filtered-product-surface-guard-products],[data-sq-military-filtered-products],[data-sq-category-universe-products],[data-sq-custom-color-products]';const oldVisible=[...document.querySelectorAll(old)].filter(visible).length;const hiddenNavVisible=[...document.querySelectorAll('[data-sq-refine-v3-hidden-nav="true"]')].filter(visible).length;const sizes=size?[...size.querySelectorAll('input')].map(i=>[i.value,i.checked]):[];const info=groups.map(g=>({label:g.querySelector(':scope>summary')?.textContent.trim()||'',open:g.open,checked:g.querySelectorAll('input:checked').length,inputs:g.querySelectorAll('input[type="checkbox"]').length}));const columns=grid?getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length:0;const structural=[...side.querySelectorAll('input[data-kind="structural"]')].map(i=>i.dataset.target||'');const native=[...side.querySelectorAll('input[data-kind="native"]')].map(i=>i.dataset.filterName||'');return{title:side.querySelector('.sq-refine-v3-sidebar__title')?.textContent.trim()||'',sizeVisible:visible(size),sizeInside:!!size?.closest('.sq-refine-v3-sidebar'),sizes,info,oldVisible,hiddenNavVisible,columns,gridVisible:visible(grid),position:getComputedStyle(side).position,height:side.getBoundingClientRect().height,combined:info.some(g=>/color\s*[\/&+]\s*pattern|color and pattern/i.test(g.label)),structural,native,script:!!document.querySelector('[data-sq-refine-v3]'),root};},route)}
function errors(d){const e=[];if(!d.script)e.push('missing V3 script');if(d.title!=='Refine Products')e.push('bad sidebar title');if(!d.sizeVisible||d.sizeInside)e.push('bad page-size placement');if(d.sizes.map(x=>x[0]).join(',')!=='50,100,250'||!d.sizes.find(x=>x[0]==='50')?.[1])e.push('bad 50/100/250 default');for(const g of d.info){if(!g.inputs)e.push('group without checkboxes: '+g.label);if(!g.checked&&g.open)e.push('inactive group open: '+g.label);if(g.checked&&!g.open)e.push('active group closed: '+g.label)}if(d.combined)e.push('combined Color/Pattern group');if(d.oldVisible)e.push('old product surface visible');if(d.hiddenNavVisible)e.push('old button tree still visible');if(d.gridVisible&&d.columns!==3)e.push('desktop grid columns='+d.columns);if(d.position!=='sticky')e.push('sidebar not sticky');if(d.height<600)e.push('sidebar too short');const handle=d.root.split('/collections/')[1];if(d.structural.some(t=>!t.includes('/collections/')||!t.includes('sq_root='+encodeURIComponent(handle))))e.push('bad structural target');if(d.native.some(n=>!n.startsWith('filter.')))e.push('bad native filter name');return e}
async function toggle(page){const details=page.locator('.sq-refine-v3-group:not([open])').first();if(!await details.count())return true;const s=details.locator(':scope>summary');const a=await s.evaluate(el=>getComputedStyle(el,'::after').content);await s.click();await delay(80);const opened=await details.getAttribute('open')!==null;const b=await s.evaluate(el=>getComputedStyle(el,'::after').content);await s.click();await delay(80);const closed=await details.getAttribute('open')===null;return /\+/.test(a)&&opened&&/[−\u2212-]/.test(b)&&closed}
async function countCards(page){return page.evaluate(()=>{const g=document.querySelector('#ResultsList')||document.querySelector('.product-grid');if(!g)return 0;return [...g.querySelectorAll(':scope>.product-grid__item,:scope>li,product-card')].filter(x=>x.matches('product-card')||x.querySelector('a[href*="/products/"]')).length})}
await fs.mkdir('cert-v3-fast',{recursive:true});
const browser=await chromium.launch({headless:true});const ctx=await browser.newContext({viewport:{width:1440,height:1000}});const page=await ctx.newPage();const report={routes:[],special:{}};
for(let i=0;i<routes.length;i++){const[name,route,type='collection']=routes[i],row={i:i+1,name,route,errors:[]};try{row.http=await nav(page,url(route));if(type==='page'){const v=await page.evaluate(()=>!!document.querySelector('[data-sq-refine-v3],.sq-refine-v3-sidebar'));if(v)row.errors.push('page received V3 collection UI')}else{row.data=await checkCollection(page,route);row.errors.push(...errors(row.data));if(!await toggle(page))row.errors.push('plus/minus toggle failed')}}catch(e){row.errors.push(String(e))}row.pass=!row.errors.length;report.routes.push(row);console.log(`${row.pass?'PASS':'FAIL'} ${i+1}/41 ${name}${row.errors.length?' :: '+row.errors.join(' | '):''}`);await delay(500)}
// State Guard is a frozen guardrail, not one of the 41 requested V3 routes.
