// Representative mobile behavior.
const mctx=await browser.newContext({viewport:{width:390,height:844}}),mp=await mctx.newPage();try{await nav(mp,url('/collections/accessories-gifts-collectibles'));await mp.waitForSelector('.sq-refine-v3-sidebar',{state:'visible',timeout:12000});report.special.mobile=await mp.evaluate(()=>{const s=document.querySelector('.sq-refine-v3-sidebar'),g=document.querySelector('#ResultsList')||document.querySelector('.product-grid'),c=g?getComputedStyle(g).gridTemplateColumns.split(' ').filter(Boolean).length:0;return{position:getComputedStyle(s).position,columns:c,pass:getComputedStyle(s).position!=='sticky'&&(!c||c===2)}})}catch(e){report.special.mobile={pass:false,error:String(e)}}await mctx.close();
// 100 and 250 must be real rendered cards, not a cosmetic selector.
report.special.pageSizes={};for(const n of [100,250]){const c=await browser.newContext({viewport:{width:1440,height:1000}}),p=await c.newPage();try{await nav(p,url('/collections/accessories-gifts-collectibles',{sq_per_page:n,sq_view_page:1}));await p.waitForSelector('.sq-refine-v3-page-size',{state:'visible',timeout:12000});await delay(n===250?5000:2500);const count=await countCards(p);report.special.pageSizes[n]={count,pass:count===n}}catch(e){report.special.pageSizes[n]={pass:false,error:String(e)}}await c.close()}
report.summary={requested:41,passed:report.routes.filter(r=>r.pass).length,failed:report.routes.filter(r=>!r.pass).length,stateGuardFrozen:!!report.special.stateGuard?.pass,mobile:!!report.special.mobile?.pass,pageSizes:Object.values(report.special.pageSizes).every(x=>x.pass)};report.summary.overall=report.summary.passed===41&&report.summary.stateGuardFrozen&&report.summary.mobile&&report.summary.pageSizes;
await fs.writeFile('cert-v3-fast/report.json',JSON.stringify(report,null,2));console.log('SUMMARY',JSON.stringify(report.summary));await ctx.close();await browser.close();if(!report.summary.overall)process.exitCode=1;
